import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const surfaceCol = new Color(colors.surface);
  const accentCol = new Color(colors.accent);

  const group = new Group();
  const content = new Group();
  group.add(content);

  // Atlas region 512x320 -> aspect 1.6
  const planeW = 0.8;
  const planeH = planeW / 1.6;

  // --- Grain background panel ---
  const panelGeo = new PlaneGeometry(planeW, planeH);
  const panelMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    opacity: 0
  });
  panelMat.colorNode = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    const grain = texture(tex);
    panelMat.colorNode = mix(
      vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b),
      vec3(surfaceCol.r + 0.03, surfaceCol.g + 0.03, surfaceCol.b + 0.045),
      grain.r.mul(0.5)
    );
    panelMat.needsUpdate = true;
  });

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = -0.002;
  content.add(panel);

  // --- Accent edge bar ---
  const barGeo = new PlaneGeometry(planeW * 0.85, 0.012);
  const barMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    opacity: 0
  });
  barMat.colorNode = vec3(accentCol.r, accentCol.g, accentCol.b);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0, -planeH * 0.38, 0.001);
  content.add(bar);

  // --- Text label ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const fontSizePx = item.typography?.fontSize ?? 39;
    const sceneSize = fontSizePx / 160;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: sceneSize,
      color: colors.paper,
      align: 'center'
    });
    textObj.position.z = 0.003;
    content.add(textObj);
  }

  // --- Entrance: rise-in + weighted-settle ---
  const tl = gsap.timeline();
  tl.from(content.position, { y: 0.25, duration: 0.7, ease: 'power3.out' });
  tl.from(content.scale, { x: 0.92, y: 0.92, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(panelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(barMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0.15);
  tl.to(content.scale, { x: 1.03, y: 1.03, duration: 0.35, ease: 'power2.out' }, 0.55);
  tl.to(content.scale, { x: 1.0, y: 1.0, duration: 0.5, ease: 'power4.out' }, 0.9);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    panelGeo.dispose();
    panelMat.dispose();
    barGeo.dispose();
    barMat.dispose();
  };

  return group;
}
